WITH base AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, level, DATEDIFF(CURRENT_DATE(), hire_date) AS days_since_hire_date FROM employees WHERE hire_date >= DATE '2023-10-19' AND manager_id IS NOT NULL) SELECT dept_id, job_title, COUNT(*) FILTER (WHERE level = 'L5') AS l5_rows, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, APPROX_PERCENTILE(days_since_hire_date, 0.9) AS days_since_hire_date_p90 FROM base GROUP BY 1, 2
